import{_ as t,o as n,c as i,a2 as r}from"./chunks/framework.mRCPFc5l.js";const h=JSON.parse('{"title":"Bedingungen bauen","description":"Vergleiche, UND/ODER und Verzweigungen — Ausdrücke, die einen Wahrheitswert liefern.","frontmatter":{"title":"Bedingungen bauen","description":"Vergleiche, UND/ODER und Verzweigungen — Ausdrücke, die einen Wahrheitswert liefern."},"headers":[],"relativePath":"apptivescript/bedingungen.md","filePath":"apptivescript/bedingungen.md","lastUpdated":1786434193000}'),d={name:"apptivescript/bedingungen.md"};function a(s,e,l,o,g,c){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="bedingungen-bauen" tabindex="-1">Bedingungen bauen <a class="header-anchor" href="#bedingungen-bauen" aria-label="Permalink to &quot;Bedingungen bauen&quot;">​</a></h1><p>Drei Stellen in ApptiveGrid erwarten eine <strong>Bedingung</strong> — einen Ausdruck, der am Ende wahr oder falsch ergibt: die <a href="/seiten/sichtbarkeit">bedingte Sichtbarkeit</a> eines Blocks, der Übergang zwischen zwei Flow-Schritten und der Filter.</p><p>Diese Seite zeigt die Bausteine und wie die drei Dialoge damit umgehen.</p><h2 id="vergleichen" tabindex="-1">Vergleichen <a class="header-anchor" href="#vergleichen" aria-label="Permalink to &quot;Vergleichen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Bedingung</th><th>Beispiel</th></tr></thead><tbody><tr><td>gleich · ungleich</td><td><code>fieldValue(&#39;status&#39;).isEqualTo(&#39;Offen&#39;)</code></td></tr><tr><td>größer · kleiner</td><td><code>fieldValue(&#39;menge&#39;).greaterThan(10)</code></td></tr><tr><td>größer/kleiner oder gleich</td><td><code>fieldValue(&#39;menge&#39;).greaterThanOrEqual(10)</code></td></tr><tr><td>enthält</td><td><code>fieldValue(&#39;titel&#39;).contains(&#39;Rechnung&#39;)</code></td></tr><tr><td>beginnt · endet mit</td><td><code>fieldValue(&#39;nummer&#39;).beginsWith(&#39;RE-&#39;)</code></td></tr><tr><td>leer · nicht leer</td><td><code>fieldValue(&#39;auftragsnummer&#39;).isNotEmpty()</code></td></tr><tr><td>wahr · falsch</td><td><code>formValues.get(&#39;agb&#39;).isTrue()</code></td></tr><tr><td>vor · nach (Datum)</td><td><code>fieldValue(&#39;frist&#39;).before(today())</code></td></tr><tr><td>Liste enthält</td><td><code>fieldValue(&#39;tags&#39;).includesAnyOf(&#39;dringend&#39;)</code></td></tr></tbody></table><p>Welche Bedingung erlaubt ist, hängt vom Typ des Wertes links ab — die vollständige Liste je Typ steht in der <a href="/referenz/apptivescript-funktionen">Funktionsreferenz</a>.</p><h2 id="mehrere-bedingungen-verknupfen" tabindex="-1">Mehrere Bedingungen verknüpfen <a class="header-anchor" href="#mehrere-bedingungen-verknupfen" aria-label="Permalink to &quot;Mehrere Bedingungen verknüpfen&quot;">​</a></h2><p>Es gibt keine Schlüsselwörter. <em>Und</em> und <em>oder</em> sind Funktionen, die auf einer Bedingung aufsetzen:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>formValues.get(&#39;alter&#39;).greaterThan(17).logicalAnd(formValues.get(&#39;agb&#39;).isTrue())</span></span></code></pre></div><p>Für mehr als zwei Bedingungen wird weiter angehängt — die Oberfläche macht es genauso:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>a.logicalAnd(b).logicalAnd(c)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Gemeint</th><th>Schreibweise</th></tr></thead><tbody><tr><td>und</td><td><code>.logicalAnd(…)</code></td></tr><tr><td>oder</td><td><code>.logicalOr(…)</code></td></tr><tr><td>nicht</td><td><code>.isFalse()</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">UND und ODER in einer Regel mischen</p><p>Technisch ist es erlaubt, aber die Oberfläche kann den Ausdruck dann nicht mehr in Zeilen zerlegen — Sie bearbeiten ihn nur noch als Ganzes. Bleiben Sie pro Regel bei <strong>einem</strong> Verknüpfungstyp. Brauchen Sie beides, ist meist ein zusätzlicher Schritt oder ein zusätzlicher Block die klarere Lösung.</p></div><h2 id="verzweigen-mit-if" tabindex="-1">Verzweigen mit <code>if</code> <a class="header-anchor" href="#verzweigen-mit-if" aria-label="Permalink to &quot;Verzweigen mit `if`&quot;">​</a></h2><p><code>if</code> ist die einzige Verzweigung der Sprache. Sie sitzt <strong>hinter</strong> der Bedingung und liefert einen von zwei Werten:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fieldValue(&#39;menge&#39;).smallerThan(5).if(&#39;nachbestellen&#39;, &#39;ok&#39;)</span></span></code></pre></div><p>Damit eignet sich <code>if</code> für Formelspalten — etwa für eine Ampel als Text. Für die Sichtbarkeit und für Flow-Übergänge brauchen Sie es nicht: dort genügt die Bedingung selbst.</p><h2 id="bedingte-sichtbarkeit-von-blocken" tabindex="-1">Bedingte Sichtbarkeit von Blöcken <a class="header-anchor" href="#bedingte-sichtbarkeit-von-blocken" aria-label="Permalink to &quot;Bedingte Sichtbarkeit von Blöcken&quot;">​</a></h2><p>Die einfache Auswahl aus <strong>Feld</strong>, <strong>Bedingung</strong> und <strong>Wert</strong> deckt acht Bedingungen ab und schreibt den Ausdruck für Sie:</p><table tabindex="0"><thead><tr><th>Auswahl</th><th>Erzeugter Ausdruck</th></tr></thead><tbody><tr><td>ist leer · ist nicht leer</td><td><code>formValues.get(&#39;key&#39;).isEmpty()</code> · <code>.isNotEmpty()</code></td></tr><tr><td>ist wahr · ist falsch</td><td><code>.isTrue()</code> · <code>.isFalse()</code></td></tr><tr><td>ist gleich · ist nicht gleich</td><td><code>.isEqualTo(&#39;Wert&#39;)</code> · <code>.isNotEqualTo(&#39;Wert&#39;)</code></td></tr><tr><td>ist größer als · ist kleiner als</td><td><code>.greaterThan(5)</code> · <code>.smallerThan(5)</code></td></tr></tbody></table><p><em>ist wahr</em> und <em>ist falsch</em> erscheinen nur bei einem Häkchen-Block. Zahlen werden ohne Anführungszeichen eingesetzt, alles andere mit.</p><p>Der Bereich <strong>Erweitert</strong> darunter zeigt den Ausdruck und lässt ihn bearbeiten. Solange er der einfachen Form entspricht, bleiben beide Ansichten synchron; sobald Sie etwas verknüpfen, führt nur noch das Textfeld weiter.</p><div class="tip custom-block"><p class="custom-block-title">Im Editor durchspielen</p><p>Neben der Sichtbarkeitsregel zeigt der Editor <strong>Aktuell sichtbar</strong> oder <strong>Aktuell ausgeblendet</strong> — für die Werte, die gerade in den Eingabeblöcken stehen. Tragen Sie testweise Werte ein und beobachten Sie den Wechsel. Das ist die schnellste Prüfung, ohne zu veröffentlichen.</p></div><p>→ <a href="/seiten/sichtbarkeit">Bedingte Sichtbarkeit</a></p><h2 id="flow-ubergange" tabindex="-1">Flow-Übergänge <a class="header-anchor" href="#flow-ubergange" aria-label="Permalink to &quot;Flow-Übergänge&quot;">​</a></h2><p>Der Dialog <strong>Nur fortfahren, wenn …</strong> an einer Verbindung zwischen zwei Schritten baut die Bedingung aus Zeilen:</p><ol><li>Oben wählen Sie <strong>Alle Bedingungen erfüllt (UND)</strong> oder <strong>Mindestens eine Bedingung (ODER)</strong>.</li><li>Jede Zeile besteht aus <strong>Wähle Wert …</strong>, <strong>Wähle Bedingung …</strong> und einem Vergleichswert.</li><li><strong>Bedingung hinzufügen</strong> ergänzt eine Zeile, das Kreuz entfernt sie.</li></ol><div class="tip custom-block"><p class="custom-block-title">Erst den Wert, dann die Bedingung</p><p>Die Liste der Bedingungen richtet sich nach dem <strong>Typ des linken Wertes</strong>. Wählen Sie den Wert zuerst, dann bleiben nur die passenden Bedingungen übrig — bei einem Datum etwa <em>before</em> und <em>after</em>.</p><p>Den Typ kennt der Dialog aus dem letzten <strong>Testlauf</strong>. Ohne Testlauf steht er auf <em>Undefined</em>, und die Liste zeigt alle Bedingungen aller Typen. → <a href="/flows/testen">Flows testen</a></p></div><p>In den Zeilen setzen Sie <strong>keine</strong> Anführungszeichen: Bei Text und Datum ergänzt der Dialog sie selbst.</p><p>Unter <strong>Erweiterte Logik</strong> steht der vollständige Ausdruck als Text. Dort schreiben Sie Verknüpfungen, die die Zeilen nicht abbilden können — und dort gelten die normalen Regeln, also auch die Anführungszeichen. Der Hinweis im Dialog sagt, wann die Eingabe greift:</p><blockquote><p><em>Wird übernommen, wenn du das Feld verlässt oder auf Speichern klickst.</em></p></blockquote><p>Zwei Meldungen können auftauchen:</p><table tabindex="0"><thead><tr><th>Meldung</th><th>Bedeutung</th></tr></thead><tbody><tr><td><em>Nicht erkannter Ausdruck</em></td><td>Diese Zeile lässt sich nicht als Wert-Bedingung-Wert lesen — bearbeiten Sie sie unter <em>Erweiterte Logik</em></td></tr><tr><td><em>Dieser Ausdruck mischt UND/ODER …</em></td><td>Die Zeilen sind gesperrt, es gilt nur noch der vollständige Ausdruck</td></tr></tbody></table><p>→ <a href="/flows/router-und-parallel">Router und Parallel</a></p><h2 id="filter" tabindex="-1">Filter <a class="header-anchor" href="#filter" aria-label="Permalink to &quot;Filter&quot;">​</a></h2><p>In einer <strong>Ansicht</strong> bauen Sie Filter ausschließlich über die Oberfläche — Feld, Bedingung, Wert. ApptiveGrid übersetzt das selbst in einen Ausdruck; ein Eingabefeld für eigene Ausdrücke gibt es dort nicht. → <a href="/ansichten/filtern-sortieren-gruppieren">Filtern, Sortieren, Gruppieren</a></p><p>Anders in einem <strong>Flow-Schritt mit Filter</strong>: Dort bietet die Werteauswahl zusätzlich <strong>Ausdruck</strong> an. Damit vergleichen Sie ein Feld nicht mit einem festen Wert, sondern mit einem berechneten — etwa mit dem Ergebnis eines vorherigen Schritts.</p><div class="warning custom-block"><p class="custom-block-title">Eine Bedingung, die nicht aufgeht, filtert aus</p><p>Ergibt ein Filterausdruck einen Fehler, nichts oder etwas anderes als einen Wahrheitswert, gilt der Eintrag als <strong>nicht zutreffend</strong> — er verschwindet aus dem Ergebnis. Eine leere Liste ist damit ein typisches Anzeichen für einen fehlerhaften Ausdruck, nicht zwangsläufig für fehlende Daten.</p></div><h2 id="typische-bedingungen" tabindex="-1">Typische Bedingungen <a class="header-anchor" href="#typische-bedingungen" aria-label="Permalink to &quot;Typische Bedingungen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ziel</th><th>Bedingung</th></tr></thead><tbody><tr><td>Zusatzfeld nur bei „Sonstiges&quot;</td><td><code>formValues.get(&#39;kategorie&#39;).isEqualTo(&#39;Sonstiges&#39;)</code></td></tr><tr><td>Bereich ab 18 Jahren</td><td><code>formValues.get(&#39;alter&#39;).greaterThan(17)</code></td></tr><tr><td>Nur mit Zustimmung fortfahren</td><td><code>formValues.get(&#39;agb&#39;).isTrue()</code></td></tr><tr><td>Zwei Bedingungen gleichzeitig</td><td><code>formValues.get(&#39;alter&#39;).greaterThan(17).logicalAnd(formValues.get(&#39;agb&#39;).isTrue())</code></td></tr><tr><td>Nur bei ausgefülltem Feld</td><td><code>step(&#39;&lt;Schritt-Id&gt;&#39;).output.get(&#39;email&#39;).isNotEmpty()</code></td></tr><tr><td>Überfällige Einträge</td><td><code>fieldValue(&#39;&lt;frist&gt;&#39;).before(today())</code></td></tr><tr><td>Alles außer einem Status</td><td><code>fieldValue(&#39;&lt;status&gt;&#39;).isNotEqualTo(&#39;Erledigt&#39;)</code></td></tr></tbody></table><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/apptivescript/editor">Der Ausdruckseditor</a> — Token-Ansicht, Picker, Beispielergebnis</li><li><a href="/apptivescript/werte-referenzieren">Werte referenzieren</a> — womit ein Ausdruck anfängt</li><li><a href="/referenz/apptivescript-funktionen">Funktionsreferenz</a> — alle Funktionen je Typ</li><li><a href="/referenz/filterbedingungen">Filterbedingungen</a> — die Bedingungen der Oberfläche im Überblick</li></ul>',42)])])}const b=t(d,[["render",a]]);export{h as __pageData,b as default};
